def backfill_challenge_expirations(apps, schema_editor):
    GameChallenge = apps.get_model('core', 'GameChallenge')
    now = timezone.now()
    batch = []
    for challenge in GameChallenge.objects.all().iterator(chunk_size=1000):
        challenge.expires_at = challenge.created_at + timedelta(days=1)
